import { afterEach, describe, expect, it } from 'vitest'
import { byteAt, startRangeServer } from './range-server.ts'
import type { Fault, RangeServer } from './range-server.ts'

// The test server that the downloader's tests read from (DESIGN.md §10.4; the iron-clad
// spec §4.7): a file of generated bytes behind `Range`, with faults that apply to the
// next requests in order. The tests of the reader and of the downloader stand on it, so
// what it answers is tested here.

const CHUNK = 64 * 1024

const servers: RangeServer[] = []

/** Starts a server that the test closes at its end, even when it fails. */
async function serve(options: {
  size: number
  seed?: number
  faults?: Fault[]
  chunkDelayMs?: number
}): Promise<RangeServer> {
  const server = await startRangeServer({ seed: 1, ...options })
  servers.push(server)
  return server
}

afterEach(async () => {
  await Promise.all(servers.splice(0).map((server) => server.close()))
})

/** The bytes of the file from `start` up to, not including, `end`. */
function expected(seed: number, start: number, end: number): Uint8Array {
  const bytes = new Uint8Array(end - start)
  for (let at = 0; at < bytes.length; at += 1) bytes[at] = byteAt(seed, start + at)
  return bytes
}

async function bytesOf(response: Response): Promise<Uint8Array> {
  return new Uint8Array(await response.arrayBuffer())
}

/** What a response gave before its body ended, and whether it ended in a failure. */
async function bytesUntilItEnds(
  response: Response,
): Promise<{ bytes: Uint8Array; failed: boolean }> {
  const reader: ReadableStreamDefaultReader<Uint8Array> | undefined = response.body?.getReader()
  if (reader === undefined) throw new Error('the response has no body')
  const parts: Uint8Array[] = []
  let failed = false
  try {
    for (;;) {
      const result = await reader.read()
      if (result.done) break
      parts.push(result.value)
    }
  } catch {
    failed = true
  }
  const bytes = new Uint8Array(parts.reduce((total, part) => total + part.length, 0))
  let at = 0
  for (const part of parts) {
    bytes.set(part, at)
    at += part.length
  }
  return { bytes, failed }
}

describe('byteAt', () => {
  it('is a pure function of the seed and the offset, and a byte', () => {
    for (let offset = 0; offset < 2000; offset += 1) {
      const value = byteAt(7, offset)
      expect(value).toBe(byteAt(7, offset))
      expect(Number.isInteger(value) && value >= 0 && value <= 255).toBe(true)
    }
  })

  it('differs with the seed', () => {
    let same = 0
    for (let offset = 0; offset < 4096; offset += 1) {
      if (byteAt(1, offset) === byteAt(2, offset)) same += 1
    }
    // Two unrelated bytes are alike once in 256 times.
    expect(same).toBeLessThan(64)
  })

  it('does not repeat at the periods a wrong offset could hide behind', () => {
    for (const period of [1, 256, 4096, 65536, 1024 * 1024, 2 ** 32]) {
      let same = 0
      for (let offset = 0; offset < 4096; offset += 1) {
        if (byteAt(3, offset) === byteAt(3, offset + period)) same += 1
      }
      expect(same, `period ${String(period)}`).toBeLessThan(64)
    }
  })

  it('spreads the values over all the bytes', () => {
    const counts = new Array<number>(256).fill(0)
    for (let offset = 0; offset < 256 * 400; offset += 1) {
      const at = byteAt(5, offset)
      counts[at] = (counts[at] ?? 0) + 1
    }
    // 400 of each is the mean; a fair spread is within a fraction of it.
    for (const count of counts) {
      expect(count).toBeGreaterThan(250)
      expect(count).toBeLessThan(550)
    }
  })

  // A guard against a generator slow enough to stall the suites that serve large files, not a
  // benchmark: an idle machine fills 64 MiB in well under a second, and turbo's parallel load has
  // been seen to take 1.7 s, so the bound leaves room for a busy machine.
  it('fills 64 MiB in a few seconds, even on a busy machine', () => {
    const bytes = new Uint8Array(64 * 1024 * 1024)
    const started = performance.now()
    for (let offset = 0; offset < bytes.length; offset += 1) bytes[offset] = byteAt(9, offset)
    const took = performance.now() - started
    expect(took).toBeLessThan(5000)
  })
})

describe('what the server answers', () => {
  it('answers a request without Range with the whole file, as a 200', async () => {
    const server = await serve({ size: 200_000, seed: 4 })
    const response = await fetch(server.url)
    expect(response.status).toBe(200)
    expect(response.headers.get('Content-Length')).toBe('200000')
    expect(response.headers.get('Accept-Ranges')).toBe('bytes')
    expect(await bytesOf(response)).toEqual(expected(4, 0, 200_000))
  })

  it('answers bytes=a- with a 206 from a to the end', async () => {
    const server = await serve({ size: 200_000, seed: 4 })
    const response = await fetch(server.url, { headers: { Range: 'bytes=150000-' } })
    expect(response.status).toBe(206)
    expect(response.headers.get('Content-Range')).toBe('bytes 150000-199999/200000')
    expect(response.headers.get('Content-Length')).toBe('50000')
    expect(await bytesOf(response)).toEqual(expected(4, 150_000, 200_000))
  })

  it('answers bytes=a-b with a 206 whose end b is included', async () => {
    const server = await serve({ size: 200_000, seed: 4 })
    const response = await fetch(server.url, { headers: { Range: 'bytes=5000-5999' } })
    expect(response.status).toBe(206)
    expect(response.headers.get('Content-Range')).toBe('bytes 5000-5999/200000')
    expect(await bytesOf(response)).toEqual(expected(4, 5000, 6000))
  })

  it('clamps an end past the end of the file', async () => {
    const server = await serve({ size: 10_000, seed: 4 })
    const response = await fetch(server.url, { headers: { Range: 'bytes=9000-99999' } })
    expect(response.status).toBe(206)
    expect(response.headers.get('Content-Range')).toBe('bytes 9000-9999/10000')
    expect(await bytesOf(response)).toEqual(expected(4, 9000, 10_000))
  })

  it('serves a file of several chunks, whole and byte for byte', async () => {
    const size = 3 * CHUNK + 123
    const server = await serve({ size, seed: 11 })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(await bytesOf(response)).toEqual(expected(11, 0, size))
  })

  it('answers a range that starts at or past the end with a 416 and the size', async () => {
    const server = await serve({ size: 1000, seed: 4 })
    for (const range of ['bytes=1000-', 'bytes=5000-6000', 'bytes=10-5']) {
      const response = await fetch(server.url, { headers: { Range: range } })
      expect(response.status, range).toBe(416)
      expect(response.headers.get('Content-Range'), range).toBe('bytes */1000')
      await response.arrayBuffer()
    }
  })

  it('answers a Range it cannot read with a 400, and anything but a GET with a 405', async () => {
    const server = await serve({ size: 1000, seed: 4 })
    const unreadable = await fetch(server.url, { headers: { Range: 'bytes=-5' } })
    expect(unreadable.status).toBe(400)
    await unreadable.arrayBuffer()
    const posted = await fetch(server.url, { method: 'POST' })
    expect(posted.status).toBe(405)
    await posted.arrayBuffer()
  })

  it('serves whatever the path and the query are', async () => {
    const server = await serve({ size: 100, seed: 4 })
    const response = await fetch(`${server.url}?token=abc&x=1`, {
      headers: { Range: 'bytes=10-19' },
    })
    expect(response.status).toBe(206)
    expect(await bytesOf(response)).toEqual(expected(4, 10, 20))
  })

  it('serves an empty file: a 200 with no body, and a 416 for any range', async () => {
    const server = await serve({ size: 0, seed: 4 })
    const whole = await fetch(server.url)
    expect(whole.status).toBe(200)
    expect((await bytesOf(whole)).length).toBe(0)
    const ranged = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(ranged.status).toBe(416)
    await ranged.arrayBuffer()
  })

  it('listens on 127.0.0.1', async () => {
    const server = await serve({ size: 10 })
    expect(server.url).toMatch(/^http:\/\/127\.0\.0\.1:\d+\//)
  })

  it('records each request’s Range, null when there is none, in order', async () => {
    const server = await serve({ size: 1000, seed: 4 })
    await (await fetch(server.url)).arrayBuffer()
    await (await fetch(server.url, { headers: { Range: 'bytes=10-' } })).arrayBuffer()
    await (await fetch(server.url, { headers: { Range: 'bytes=20-29' } })).arrayBuffer()
    expect(server.requests).toEqual([
      { range: null },
      { range: 'bytes=10-' },
      { range: 'bytes=20-29' },
    ])
  })
})

describe('the faults', () => {
  it('a status fault answers that status with an empty body and its Retry-After', async () => {
    const server = await serve({
      size: 1000,
      faults: [{ kind: 'status', status: 503, retryAfter: '2' }],
    })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(response.status).toBe(503)
    expect(response.headers.get('Retry-After')).toBe('2')
    expect((await bytesOf(response)).length).toBe(0)
  })

  it('a status fault without retryAfter sends no Retry-After', async () => {
    const server = await serve({ size: 1000, faults: [{ kind: 'status', status: 404 }] })
    const response = await fetch(server.url)
    expect(response.status).toBe(404)
    expect(response.headers.get('Retry-After')).toBeNull()
    await response.arrayBuffer()
  })

  it('each fault applies to one request, in order, and the requests after them are served', async () => {
    const server = await serve({
      size: 1000,
      seed: 4,
      faults: [
        { kind: 'status', status: 500 },
        { kind: 'status', status: 429 },
      ],
    })
    const statuses: number[] = []
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
      statuses.push(response.status)
      await response.arrayBuffer()
    }
    expect(statuses).toEqual([500, 429, 206])
    expect(server.requests.length).toBe(3)
  })

  it('an ignore-range fault answers a 200 with the whole file whatever the Range', async () => {
    const server = await serve({ size: 200_000, seed: 4, faults: [{ kind: 'ignore-range' }] })
    const response = await fetch(server.url, { headers: { Range: 'bytes=5000-5999' } })
    expect(response.status).toBe(200)
    expect(response.headers.get('Content-Range')).toBeNull()
    expect(response.headers.get('Content-Length')).toBe('200000')
    expect(await bytesOf(response)).toEqual(expected(4, 0, 200_000))
  })

  it('a drop fault sends the headers and afterBytes bytes, then breaks the connection', async () => {
    const server = await serve({
      size: 200_000,
      seed: 4,
      faults: [{ kind: 'drop', afterBytes: 1000 }],
    })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(response.status).toBe(206)
    expect(response.headers.get('Content-Length')).toBe('200000')
    const { bytes, failed } = await bytesUntilItEnds(response)
    expect(failed).toBe(true)
    expect(bytes).toEqual(expected(4, 0, 1000))
  })

  it('a drop past the chunk size still cuts the body at the byte', async () => {
    const server = await serve({
      size: 400_000,
      seed: 4,
      faults: [{ kind: 'drop', afterBytes: CHUNK + 500 }],
    })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    const { bytes, failed } = await bytesUntilItEnds(response)
    expect(failed).toBe(true)
    expect(bytes.length).toBe(CHUNK + 500)
  })

  it('a drop after 0 bytes sends the headers and then breaks the connection', async () => {
    const server = await serve({
      size: 200_000,
      seed: 4,
      faults: [{ kind: 'drop', afterBytes: 0 }],
    })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(response.status).toBe(206)
    await expect(response.arrayBuffer()).rejects.toBeInstanceOf(TypeError)
  })

  it('a drop after more bytes than the body has sends the body whole', async () => {
    const server = await serve({
      size: 1000,
      seed: 4,
      faults: [{ kind: 'drop', afterBytes: 5000 }],
    })
    const response = await fetch(server.url, { headers: { Range: 'bytes=0-' } })
    expect(await bytesOf(response)).toEqual(expected(4, 0, 1000))
  })

  it('a delay fault waits between the chunks of that response only', async () => {
    const server = await serve({
      size: 3 * CHUNK,
      seed: 4,
      faults: [{ kind: 'delay', ms: 100 }],
    })
    const started = performance.now()
    await (await fetch(server.url)).arrayBuffer()
    const slow = performance.now() - started
    // Three chunks have two gaps between them.
    expect(slow).toBeGreaterThanOrEqual(180)
    const next = performance.now()
    await (await fetch(server.url)).arrayBuffer()
    expect(performance.now() - next).toBeLessThan(150)
  })

  it('chunkDelayMs waits between the chunks of every response that has no delay fault', async () => {
    const server = await serve({ size: 3 * CHUNK, seed: 4, chunkDelayMs: 100 })
    for (let attempt = 0; attempt < 2; attempt += 1) {
      const started = performance.now()
      await (await fetch(server.url)).arrayBuffer()
      expect(performance.now() - started).toBeGreaterThanOrEqual(180)
    }
  })

  it('a delay fault replaces chunkDelayMs for its response', async () => {
    const server = await serve({
      size: 3 * CHUNK,
      seed: 4,
      chunkDelayMs: 300,
      faults: [{ kind: 'delay', ms: 10 }],
    })
    const started = performance.now()
    await (await fetch(server.url)).arrayBuffer()
    expect(performance.now() - started).toBeLessThan(400)
  })
})

describe('the server’s end', () => {
  /** Polls until `check` holds or the time is up. */
  async function until(check: () => boolean, ms = 2000): Promise<void> {
    const stop = Date.now() + ms
    while (!check() && Date.now() < stop) await new Promise((resolve) => setTimeout(resolve, 10))
  }

  it('lets go of a response whose client went away mid-body', async () => {
    const server = await serve({ size: 8 * 1024 * 1024, seed: 4, chunkDelayMs: 20 })
    const controller = new AbortController()
    const response = await fetch(server.url, { signal: controller.signal })
    const reader = response.body?.getReader()
    if (reader === undefined) throw new Error('the response has no body')
    await reader.read()
    expect(server.openResponses()).toBe(1)
    controller.abort()
    await expect(reader.read()).rejects.toMatchObject({ name: 'AbortError' })
    await until(() => server.openResponses() === 0)
    expect(server.openResponses()).toBe(0)
  })

  it('counts a response that finished as no longer open', async () => {
    const server = await serve({ size: 1000, seed: 4 })
    await (await fetch(server.url)).arrayBuffer()
    await until(() => server.openResponses() === 0)
    expect(server.openResponses()).toBe(0)
  })

  it('close() ends the responses that are open and resolves, and may be called twice', async () => {
    const server = await startRangeServer({
      size: 8 * 1024 * 1024,
      seed: 4,
      chunkDelayMs: 50,
    })
    const response = await fetch(server.url)
    const reader = response.body?.getReader()
    if (reader === undefined) throw new Error('the response has no body')
    await reader.read()
    const closing = server.close()
    await closing
    await server.close()
    await expect(
      (async () => {
        for (;;) {
          const { done } = await reader.read()
          if (done) return
        }
      })(),
    ).rejects.toBeInstanceOf(Error)
  })

  it('refuses new connections once closed', async () => {
    const server = await startRangeServer({ size: 10, seed: 4 })
    await server.close()
    await expect(fetch(server.url)).rejects.toBeInstanceOf(TypeError)
  })
})
